1	import type { StorageProvider as StorageProviderId } from "@paperclipai/shared";
2	
3	/**
4	 * Local copies of the StorageProvider interface types from
5	 * `server/src/storage/types.ts`. We duplicate only the shapes needed here
6	 * because importing Node-typed server modules into a Worker bundle would pull
7	 * in `node:stream` and other Node-only dependencies.
8	 *
9	 * Keep these in sync with `server/src/storage/types.ts`.
10	 */
11	export interface PutObjectInput {
12	  objectKey: string;
13	  body: Uint8Array | ArrayBuffer;
14	  contentType: string;
15	  contentLength: number;
16	}
17	
18	export interface GetObjectInput {
19	  objectKey: string;
20	}
21	
22	export interface GetObjectResult {
23	  /** ReadableStream — Workers environment returns Web Streams, not Node Readable. */
24	  stream: ReadableStream;
25	  contentType?: string;
26	  contentLength?: number;
27	  etag?: string;
28	  lastModified?: Date;
29	}
30	
31	export interface HeadObjectResult {
32	  exists: boolean;
33	  contentType?: string;
34	  contentLength?: number;
35	  etag?: string;
36	  lastModified?: Date;
37	}
38	
39	export interface StorageProvider {
40	  id: StorageProviderId;
41	  putObject(input: PutObjectInput): Promise<void>;
42	  getObject(input: GetObjectInput): Promise<GetObjectResult>;
43	  headObject(input: GetObjectInput): Promise<HeadObjectResult>;
44	  deleteObject(input: GetObjectInput): Promise<void>;
45	}
46	
47	export interface R2ProviderConfig {
48	  /** Logical bucket name — recorded on stored objects for observability. */
49	  bucket: string;
50	  /**
51	   * Optional key prefix applied to every object key before passing to R2.
52	   * Useful when sharing a single R2 bucket across multiple environments.
53	   * Example: `"prod/"` → all keys become `"prod/<objectKey>"`.
54	   */
55	  prefix: string;
56	}
57	
58	/**
59	 * `StorageProvider` implementation backed by Cloudflare R2.
60	 *
61	 * R2 is S3-compatible at the conceptual level but exposes a native binding
62	 * API (`R2Bucket`) in Workers rather than the AWS SDK. This provider wraps
63	 * that binding to satisfy the `StorageProvider` contract used throughout the
64	 * server package.
65	 *
66	 * The `stream` field in `GetObjectResult` is a `ReadableStream` (Web Streams
67	 * API) rather than a Node `Readable`. Callers in the Workers environment
68	 * should consume it directly. If a Node `Readable` is needed (e.g. in a
69	 * test shim), wrap it: `Readable.fromWeb(result.stream)`.
70	 */
71	export class R2Provider implements StorageProvider {
72	  readonly id: StorageProviderId = "r2";
73	
74	  private readonly bucket: R2Bucket;
75	  private readonly prefix: string;
76	
77	  constructor(bucket: R2Bucket, config: R2ProviderConfig) {
78	    this.bucket = bucket;
79	    this.prefix = config.prefix;
80	  }
81	
82	  private key(objectKey: string): string {
83	    return this.prefix ? `${this.prefix}${objectKey}` : objectKey;
84	  }
85	
86	  async putObject(input: PutObjectInput): Promise<void> {
87	    await this.bucket.put(this.key(input.objectKey), input.body, {
88	      httpMetadata: { contentType: input.contentType },
89	    });
90	  }
91	
92	  async getObject(input: GetObjectInput): Promise<GetObjectResult> {
93	    const obj = await this.bucket.get(this.key(input.objectKey));
94	    if (!obj) {
95	      throw new Error(`R2: object not found: ${input.objectKey}`);
96	    }
97	    return {
98	      // R2ObjectBody.body is a ReadableStream<Uint8Array> — cast to the
99	      // opaque ReadableStream type our interface declares.
100	      stream: obj.body as unknown as ReadableStream,
101	      contentType: obj.httpMetadata?.contentType,
102	      contentLength: obj.size,
103	      etag: obj.etag,
104	      lastModified: obj.uploaded,
105	    };
106	  }
107	
108	  async headObject(input: GetObjectInput): Promise<HeadObjectResult> {
109	    const obj = await this.bucket.head(this.key(input.objectKey));
110	    if (!obj) {
111	      return { exists: false };
112	    }
113	    return {
114	      exists: true,
115	      contentType: obj.httpMetadata?.contentType,
116	      contentLength: obj.size,
117	      etag: obj.etag,
118	      lastModified: obj.uploaded,
119	    };
120	  }
121	
122	  async deleteObject(input: GetObjectInput): Promise<void> {
123	    await this.bucket.delete(this.key(input.objectKey));
124	  }
125	}
